import json, re, unicodedata as ud
from datetime import datetime, timezone
from typing import Tuple, Dict, Any, List, Iterable

REQUIRED_KEYS = ("symbol","price","currency","timestamp","source")
KEY_RE = re.compile(r"^[A-Za-z_]+$")
NUM_RE_POS = re.compile(r"^(0|[1-9][0-9]*)(\.[0-9]{1,6})?$")
ISO_Z_RE = re.compile(r"^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$")
RAW_NUM_TOKEN_RE = re.compile(r'"(?P<key>price)"\s*:\s*(?P<tok>[-+]?[0-9]+(?:\.[0-9]+)?(?:[eE][-+]?[0-9]+)?)')

def _nfkc_eq(s: str) -> bool:
    return ud.normalize("NFKC", s) == s

def _ascii_printable(s: str) -> bool:
    return all(0x20 <= ord(c) <= 0x7E for c in s)

def _parse_iso_z(ts: str):
    try:
        if not ISO_Z_RE.match(ts):
            return None
        return datetime(int(ts[0:4]), int(ts[5:7]), int(ts[8:10]),
                        int(ts[11:13]), int(ts[14:16]), int(ts[17:19]),
                        tzinfo=timezone.utc)
    except Exception:
        return None

def _render_plain_decimal(n):
    if isinstance(n, int): return str(n)
    s = ("%.12f" % float(n)).rstrip('0').rstrip('.')
    return s if s else "0"

def validate_quote_response(raw_bytes: bytes,
                            content_type: str,
                            scheme: str,
                            now_utc: datetime,
                            allowed_symbols: Iterable[str],
                            currency_whitelist: Iterable[str]=("USD",),
                            recency_s: int=60) -> Tuple[bool, Dict[str, Any]]:
    # 1) Headers/transport
    if not content_type or "application/json" not in content_type.lower():
        return False, {"error":"REJECT_CONTENT_TYPE","detail":content_type or ""}
    if scheme.lower() != "https":
        return False, {"error":"REJECT_INSECURE_TRANSPORT","detail":scheme}
    # 2) UTF-8 + size
    try:
        if raw_bytes.startswith(b"\xEF\xBB\xBF") and len(raw_bytes) > 3:
            return False, {"error":"REJECT_UTF8","detail":"BOM beyond byte 0"}
        if len(raw_bytes) > 8*1024:
            return False, {"error":"REJECT_TOO_LARGE","detail":len(raw_bytes)}
        s = raw_bytes.decode("utf-8", errors="strict")
    except UnicodeDecodeError as e:
        return False, {"error":"REJECT_UTF8","detail":str(e)}
    # 3) ASCII envelope
    for i,ch in enumerate(s):
        o=ord(ch)
        if o<0x20 and o not in (0x09,0x0A,0x0D): return False, {"error":"REJECT_ASCII_ENVELOPE","pos":i,"byte":"0x%02X"%o}
        if o>0x7E: return False, {"error":"REJECT_ASCII_ENVELOPE","pos":i,"byte":"0x%02X"%o}
    # 3b) Pre-parse sci-notation
    m = RAW_NUM_TOKEN_RE.search(s)
    if m and ('e' in m.group("tok") or 'E' in m.group("tok")):
        return False, {"error":"REJECT_NUMERIC_SCI_NOTATION","field":"price","token":m.group("tok")}
    # 4) Parse
    try:
        obj = json.loads(s)
    except json.JSONDecodeError as e:
        return False, {"error":"REJECT_JSON_SYNTAX","detail":str(e)}
    if not isinstance(obj, dict):
        return False, {"error":"REJECT_TOPLEVEL_TYPE","detail":type(obj).__name__}
    # 5) Keys/canonicalization
    keys = tuple(obj.keys())
    if set(keys) != set(REQUIRED_KEYS):
        extra=[k for k in keys if k not in REQUIRED_KEYS]
        missing=[k for k in REQUIRED_KEYS if k not in obj]
        return False, {"error":"REJECT_KEY_SET","missing":missing,"extra":extra}
    seen=set()
    for k in keys:
        if not _ascii_printable(k) or not KEY_RE.match(k):
            return False, {"error":"REJECT_KEY_ASCII","key":k}
        if not _nfkc_eq(k):
            return False, {"error":"REJECT_KEY_NFKC_CHANGED","key":k}
        if k in seen:
            return False, {"error":"REJECT_KEY_DUPLICATE","key":k}
        seen.add(k)
    # 6) Fields
    sym = obj["symbol"]
    if not isinstance(sym, str) or not _ascii_printable(sym) or not (1<=len(sym)<=5) or not sym.isalpha() or not sym.isupper() or not _nfkc_eq(sym):
        return False, {"error":"SYMBOL_FORMAT","value":sym}
    if allowed_symbols and sym not in set(allowed_symbols):
        return False, {"error":"SYMBOL_NOT_ALLOWED","value":sym}
    price = obj["price"]
    if not isinstance(price, (int,float)):
        return False, {"error":"PRICE_NUMERIC","detail":"not number"}
    price_str = _render_plain_decimal(price)
    if not NUM_RE_POS.match(price_str):
        return False, {"error":"PRICE_NUMERIC","detail":"regex"}
    price_val = float(price_str)
    if not (0.0 < price_val < 1_000_000.0):
        return False, {"error":"PRICE_RANGE","value":price_val}
    cur = obj["currency"]
    if not isinstance(cur, str) or not _ascii_printable(cur) or not _nfkc_eq(cur) or cur not in tuple(currency_whitelist):
        return False, {"error":"CURRENCY_WHITELIST","value":cur}
    ts = obj["timestamp"]
    if not isinstance(ts, str) or not _ascii_printable(ts) or not _nfkc_eq(ts):
        return False, {"error":"TIMESTAMP_ASCII","value":ts}
    dt = _parse_iso_z(ts)
    if dt is None:
        return False, {"error":"TIMESTAMP_PARSE","value":ts}
    skew_future = (dt - now_utc).total_seconds()
    if skew_future > 5:
        return False, {"error":"CLOCK_SKEW_FUTURE","skew_seconds":skew_future}
    stale = (now_utc - dt).total_seconds() > recency_s
    src = obj["source"]
    if not isinstance(src, str) or not _ascii_printable(src) or not (1<=len(src)<=40) or not _nfkc_eq(src):
        return False, {"error":"SOURCE_ASCII","value":src}
    # 7) Return normalized
    return True, {"symbol":sym,"price":price_val,"currency":cur,"timestamp":ts,"source":src,"stale":bool(stale),"recency_s":recency_s}

def format_scribe(quotes: List[Dict[str,Any]]) -> List[str]:
    # quotes = list of accepted data dicts; withhold any stale
    parts=[]
    any_stale=False
    for q in quotes:
        if q.get("stale"):
            parts.append(f"{q['symbol']} [withheld, stale]")
            any_stale=True
        else:
            parts.append(f"{q['symbol']} [USD {q['price']:.2f}, {q['timestamp'][11:19]} Z, {q['source']}]")
    line1 = "In this hour, I set down thus: " + "; ".join(parts) + "."
    line2 = "Outlook in brief: momentum seems mixed with medium uncertainty amid broad market drift."
    line3 = ("I shall not pen false ciphers; bid me fetch again anon." if any_stale
             else "As any faithful scribe, I note the bells’ time above; figures may shift with the next toll.")
    return [line1, line2, line3]

