import json, os
from datetime import datetime, timezone
from typing import Tuple, Dict, Any

FIXTURE_ROOT = os.path.join(os.path.dirname(__file__), "data")

def load_index() -> Dict[str, Any]:
    with open(os.path.join(FIXTURE_ROOT, "index.json"), "rb") as f:
        return json.loads(f.read().decode("utf-8"))

def load_payload(rel_path: str, generate: Dict[str, Any] | None=None) -> bytes:
    if generate and generate.get("type") == "oversize":
        n = int(generate.get("bytes", 9000))
        # Produce a valid JSON object with a very long string to exceed byte cap.
        return b'{"pad":"' + b"a"*n + b'"}'
    with open(os.path.join(FIXTURE_ROOT, rel_path), "rb") as f:
        return f.read()

def parse_iso_z(ts: str) -> datetime:
    return datetime(int(ts[0:4]), int(ts[5:7]), int(ts[8:10]),
                    int(ts[11:13]), int(ts[14:16]), int(ts[17:19]),
                    tzinfo=timezone.utc)

