import json, re, unicodedata as ud
from datetime import datetime, timezone
from typing import Tuple, Dict, Any, List

REQUIRED_KEYS = ("location","temperature","unit","humidity","wind_speed","wind_unit","timestamp","source")
KEY_RE = re.compile(r"^[A-Za-z_]+$")
NUM_RE_TEMP = re.compile(r"^-?(0|[1-9][0-9]*)(\.[0-9]{1,2})?$")
NUM_RE_POS = re.compile(r"^(0|[1-9][0-9]*)(\.[0-9]{1,2})?$")
INT_RE = re.compile(r"^(0|[1-9][0-9]*)$")
ISO_Z_RE = re.compile(r"^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$")

def _hex_cp(ch: str) -> str:
    return "U+%04X" % ord(ch)

def _hex_byte(b: int) -> str:
    return "0x%02X" % b

def _nfkc_eq(s: str) -> bool:
    return ud.normalize("NFKC", s) == s

def _ascii_printable(s: str) -> bool:
    return all(0x20 <= ord(c) <= 0x7E for c in s)

def _parse_iso_z(ts: str):
    try:
        if not ISO_Z_RE.match(ts):
            return None
        return datetime(int(ts[0:4]), int(ts[5:7]), int(ts[8:10]),
                        int(ts[11:13]), int(ts[14:16]), int(ts[17:19]),
                        tzinfo=timezone.utc)
    except Exception:
        return None

def _num_is_scientific(n: Any) -> bool:
    # Numbers that came from JSON numeric tokens will be int/float in Python.
    # Detect scientific notation by re-rendering in a canonical plain form and checking for 'e'/'E'.
    s = ("%.12g" % n)
    return 'e' in s or 'E' in s

def _render_plain_decimal(n: Any) -> str:
    # Canonical non-scientific rendering (up to 12 significant digits), strip trailing zeros/dot.
    if isinstance(n, int):
        return str(n)
    s = ("%.12f" % float(n)).rstrip('0').rstrip('.')
    return s if s else "0"

def _freshness_window(severe: bool=False) -> int:
    return 150 if severe else 300  # seconds

def validate_weather_response(raw_bytes: bytes,
                              content_type: str,
                              scheme: str,
                              now_utc: datetime) -> Tuple[bool, Dict[str, Any]]:
    # 1) Transport/headers
    if not content_type or "application/json" not in content_type.lower() or "charset=utf-8" not in content_type.lower():
        return False, {"error":"REJECT_CONTENT_TYPE","detail":content_type or ""}
    if scheme.lower() != "https":
        return False, {"error":"REJECT_INSECURE_TRANSPORT","detail":scheme}

    # 2) UTF-8 decode strict
    try:
        if raw_bytes.startswith(b"\xEF\xBB\xBF") and len(raw_bytes) > 3:
            return False, {"error":"REJECT_UTF8","detail":"BOM beyond byte 0"}
        s = raw_bytes.decode("utf-8", errors="strict")
    except UnicodeDecodeError as e:
        return False, {"error":"REJECT_UTF8","detail":str(e)}

    # 3) ASCII envelope pre-parse
    for i, ch in enumerate(s):
        b = ord(ch)
        if b < 0x20 and b not in (0x09,0x0A,0x0D):
            return False, {"error":"REJECT_ASCII_ENVELOPE","detail":_hex_byte(b), "pos":i}
        if b > 0x7E:
            return False, {"error":"REJECT_ASCII_ENVELOPE","detail":_hex_byte(b), "pos":i}

    # 4) JSON parse strict
    try:
        obj = json.loads(s)
    except json.JSONDecodeError as e:
        return False, {"error":"REJECT_JSON_SYNTAX","detail":str(e)}
    if not isinstance(obj, dict):
        return False, {"error":"REJECT_TOPLEVEL_TYPE","detail":type(obj).__name__}
    if len(s) > 8*1024:
        return False, {"error":"REJECT_TOO_LARGE","detail":len(s)}

    # 5) Key set and canonicalization
    keys = tuple(obj.keys())
    if set(keys) != set(REQUIRED_KEYS):
        extra = [k for k in keys if k not in REQUIRED_KEYS]
        missing = [k for k in REQUIRED_KEYS if k not in obj]
        return False, {"error":"REJECT_KEY_SET","missing":missing,"extra":extra}
    canon = {}
    for k in keys:
        if not _ascii_printable(k) or not KEY_RE.match(k):
            return False, {"error":"REJECT_KEY_ASCII","key":k}
        if not _nfkc_eq(k):
            return False, {"error":"REJECT_KEY_NFKC_CHANGED","key":k}
        if k in canon:
            return False, {"error":"REJECT_KEY_DUPLICATE","key":k}
        canon[k] = k

    # 6) Field-level checks
    v = obj["location"]
    if not isinstance(v, str) or not _ascii_printable(v) or not (1 <= len(v) <= 40) or not _nfkc_eq(v) or any(c in v for c in ",\n\r\t"):
        return False, {"error":"VALUE_ASCII_LOCATION","value":v}

    t = obj["temperature"]
    if not isinstance(t, (int,float)):
        return False, {"error":"TEMP_NUMERIC","detail":"not number"}
    t_str = _render_plain_decimal(t)
    if not NUM_RE_TEMP.match(t_str):
        return False, {"error":"TEMP_NUMERIC","detail":"regex"}
    if _num_is_scientific(t):
        return False, {"error":"TEMP_NUMERIC","detail":"scientific"}
    t_val = float(t_str)
    if not (-100.0 <= t_val <= 70.0):
        return False, {"error":"TEMP_RANGE","value":t_val}

    u = obj["unit"]
    if not isinstance(u, str) or u not in ("C","F") or not _nfkc_eq(u) or not _ascii_printable(u):
        return False, {"error":"UNIT_WHITELIST","value":u}

    h = obj["humidity"]
    if not isinstance(h, (int,float)):
        return False, {"error":"HUMIDITY_NUMERIC","detail":"not number"}
    h_str = _render_plain_decimal(h)
    if not INT_RE.match(h_str):
        return False, {"error":"HUMIDITY_INTEGER","value":h_str}
    h_val = int(h_str)
    if not (0 <= h_val <= 100):
        return False, {"error":"HUMIDITY_RANGE","value":h_val}

    ws = obj["wind_speed"]
    if not isinstance(ws, (int,float)):
        return False, {"error":"WIND_NUMERIC","detail":"not number"}
    ws_str = _render_plain_decimal(ws)
    if not NUM_RE_POS.match(ws_str):
        return False, {"error":"WIND_NUMERIC","detail":"regex"}
    if _num_is_scientific(ws):
        return False, {"error":"WIND_NUMERIC","detail":"scientific"}
    ws_val = float(ws_str)
    if not (0.0 <= ws_val <= 200.0):
        return False, {"error":"WIND_RANGE","value":ws_val}

    wu = obj["wind_unit"]
    if not isinstance(wu, str) or wu not in ("mps","kmh","mph") or not _nfkc_eq(wu) or not _ascii_printable(wu):
        return False, {"error":"WIND_UNIT_WHITELIST","value":wu}

