import json
from datetime import datetime, timezone
from validators.strict_weather_validator import validate_weather_response
from validators.strict_quote_validator import validate_quote_response
from tests.util_fixtures import load_index, load_payload, parse_iso_z

def test_fixtures_weather_and_quotes():
    idx = load_index()
    now_wx = parse_iso_z(idx["weather_now"])
    now_q = parse_iso_z(idx["quotes_now"])

    # Weather
    for case in idx["weather"]:
        raw = load_payload(case["file"], case.get("generate"))
        ok, out = validate_weather_response(raw, case["content_type"], case["scheme"], now_wx)
        exp = case["expect"]
        if exp["ok"]:
            assert ok, f"{case['file']} expected ok"
            if "stale" in exp:
                assert out["stale"] is exp["stale"], f"{case['file']} stale mismatch"
        else:
            assert not ok and out.get("error") == exp["error"], f"{case['file']} expected {exp['error']}, got {out}"

    # Quotes
    for case in idx["quotes"]:
        raw = load_payload(case["file"], case.get("generate"))
        ok, out = validate_quote_response(raw, case["content_type"], case["scheme"], now_q, tuple(case.get("allowed_symbols", [])))
        exp = case["expect"]
        if exp["ok"]:
            assert ok, f"{case['file']} expected ok"
            if "stale" in exp:
                assert out["stale"] is exp["stale"], f"{case['file']} stale mismatch"
        else:
            assert not ok and out.get("error") == exp["error"], f"{case['file']} expected {exp['error']}, got {out}"

Notes
- All non-ASCII literals meant to trip the ASCII envelope are included directly (e.g., ℃, ZWSP, fullwidth). Ensure your editor saves these files as UTF-8.
- For cases using \uXXXX escapes, the ASCII envelope passes pre-parse, and the rejection happens post-parse (e.g., TEMP_NUMERIC for string temperature or UNIT_WHITELIST for non-ASCII unit).
- Oversize payloads are generated by the loader, so the fixture files remain small.

